def transform(grid):
    """Extend the observed diagonal stripe coloring periodically."""
    h, w = len(grid), len(grid[0])
    marks = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in marks and marks[d] != color:
                    raise ValueError("conflicting colors on one diagonal")
                marks[d] = color
    if not marks:
        raise ValueError("no diagonal clues")

    # Parallel stripe tasks provide one or more clue diagonals for each
    # position in the repeating color cycle. The number of distinct clue
    # diagonals gives the cycle length for these task instances.
    period = len(marks)
    phases = {}
    for d, color in marks.items():
        phase = d % period
        if phase in phases and phases[phase] != color:
            raise ValueError("inconsistent periodic diagonal clues")
        phases[phase] = color
    if len(phases) != period:
        raise ValueError("incomplete diagonal color cycle")
    return [[phases[(c - r) % period] for c in range(w)] for r in range(h)]

