def transform(grid):
    """Infer the shortest repeating horizontal row-color cycle from nonzero stripe clues."""
    h, w = len(grid), len(grid[0])
    clues = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0:
            clues.append((r, row[0]))
    if not clues:
        raise ValueError("no stripe clues")
    # The smallest cycle length consistent with all observed row stripes.
    period = next((p for p in range(1, h + 1)
                   if all(not any((rr - r) % p == 0 and cc != c
                                  for rr, cc in clues)
                          for r, c in clues)), None)
    if period is None:
        raise ValueError("no consistent period")
    cycle = {}
    for r, c in clues:
        phase = r % period
        if phase in cycle and cycle[phase] != c:
            raise ValueError("inconsistent phase")
        cycle[phase] = c
    if len(cycle) != period:
        raise ValueError("clues do not determine full cycle")
    return [[cycle[r % period] for _ in range(w)] for r in range(h)]
